            }
            if (onHold(invoice.getClientId())) {
                throw new InvoiceRejectedException("The client is on hold: lift the hold before sending their invoices.");
            }
            if (invoice.isCreditNote()) {
                String refusal = creditNoteRefusal(invoice);
                if (refusal != null) {
